        # pursuit_evasion
        else:
            # if closer than opponent-like threat, maintain pressure or escape based on relative positions
            score += 2 * (abs(sx - ox) + abs(sy - oy) - d_opp)

            # mild preference for reducing axis distance when far
            score -= abs(nx - ox) + abs(ny - oy)

        # territory_control
        if has_territory:
            if territory:
                dt = min(abs(nx - x) + abs(ny - y) for x, y in territory)
                score += 4 - dt
            if owned:
                do = min(abs(nx - x) + abs(ny - y) for x, y in owned)
                score -= 2 * max(0, 2 - do)
            if unowned:
                du = min(abs(nx - x) + abs(ny - y) for x, y in unowned)
                score += 2 - du

        # center bias for open maps
        if w and h:
            cx = (w - 1) / 2.0
            cy = (h - 1) / 2.0
            score -= (abs(nx - cx) + abs(ny - cy)) * 0.05

